// SPIDEY COLLECTIONS — Centralized Store & Synchronization Engine
const SPIDEY_STORAGE_KEY = 'spidey_store_data_v2';
const SPIDEY_ORDERS_KEY = 'spidey_orders_data_v2';
const SPIDEY_SUBS_KEY = 'spidey_subscribers_data_v2';
let _spideyChannel = null;
try {
  if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
    _spideyChannel = new BroadcastChannel('spidey_store_bus');
    _spideyChannel.onmessage = function(e) {
      if (e && e.data && e.data.type === 'spidey_store_updated') {
        try {
          window.dispatchEvent(new CustomEvent('spidey_store_updated', { detail: e.data.data }));
        } catch(err) {}
      }
    };
  }
} catch (e) {}

if (typeof window !== 'undefined') {
  window.addEventListener('storage', function(e) {
    if (e.key === SPIDEY_STORAGE_KEY || e.key === 'spidey_store_ping') {
      try {
        const fresh = window.SpideyStore ? window.SpideyStore.getData() : null;
        if (fresh) {
          window.dispatchEvent(new CustomEvent('spidey_store_updated', { detail: fresh }));
        }
      } catch (err) {}
    }
  });
}

